1	import {
2	  useEffect,
3	  useEffectEvent,
4	  useRef,
5	  useState,
6	  type ChangeEvent,
7	  type FormEvent,
8	  type SyntheticEvent,
9	} from "react";
10	import { SESSION_TYPES, VISIBILITIES } from "../../shared/api/types.ts";
11	import type { SessionType, Visibility } from "../../shared/api/types.ts";
12	import { currentTime, formatTimeZoneName } from "../../shared/lib/datetime.ts";
13	import { copy } from "./copy.ts";
14	import { ariaFor } from "./aria.ts";
15	import { Field, FieldError } from "./Field.tsx";
16	import {
17	  ERROR_ORDER,
18	  FIELD_SERVER_KEY,
19	  INITIAL_VALUES,
20	  isDirty,
21	  splitServerErrors,
22	  toRequest,
23	  type ErrorKey,
24	  type FieldName,
25	  type FormValues,
26	} from "./form-values.ts";
27	import { SuccessScreen } from "./SuccessScreen.tsx";
28	import { useCoaches } from "./useCoaches.ts";
29	import { useCreateSession } from "./useCreateSession.ts";
30	import { LIMITS, validate } from "./validate.ts";
31	
32	export interface CreateSessionDialogProps {
33	  /** Активны ли фильтры списка (подсказка и «Clear filters» на экране успеха). */
34	  filtersActive: boolean;
35	  /** Закрытие диалога; `refetch` — исход POST был неизвестен (сеть, malformed), список нужно перезапросить. */
36	  onClose: (result: { refetch: boolean }) => void;
37	  /** Сессия создана (201): владелец списка перезапрашивает его. */
38	  onCreated: () => void;
39	  onOpenSession: (id: string) => void;
40	  onClearFilters: () => void;
41	}
42	
43	const FIELD_IDS: Record<ErrorKey, string> = {
44	  title: "cs-title",
45	  type: "cs-type",
46	  date: "cs-date",
47	  time: "cs-time",
48	  startsAt: "cs-date",
49	  duration: "cs-duration",
50	  capacity: "cs-capacity",
51	  coachId: "cs-coach",
52	  locationName: "cs-location-name",
53	  locationAddress: "cs-location-address",
54	  visibility: "cs-visibility-public",
55	  description: "cs-description",
56	  trainerNotes: "cs-notes",
57	};
58	
59	const COACH_RETRY_ID = "cs-coaches-retry";
60	const DESCRIPTION_COUNTER_FROM = 800;
61	const NOTES_COUNTER_FROM = 400;
62	
63	/** Фокус при открытии: Title на десктопе, заголовок при coarse-указателе (клавиатура не поднимается). */
64	function focusInitial(dialog: HTMLElement): void {
65	  const coarse = typeof window.matchMedia === "function" && window.matchMedia("(pointer: coarse)").matches;
66	  const target = coarse ? dialog.querySelector<HTMLElement>("h2") : document.getElementById(FIELD_IDS.title);
67	  target?.focus({ preventScroll: true });
68	}
69	
70	function restoreFocus(opener: HTMLElement | null): void {
71	  // Открыватель мог исчезнуть (кнопка пустого состояния): запасной вариант — кнопка в шапке.
72	  const target = opener?.isConnected ? opener : document.querySelector<HTMLElement>("[data-create-trigger]");
73	  target?.focus();
74	}
75	
76	function isSessionType(value: string): value is SessionType {
77	  return (SESSION_TYPES as readonly string[]).includes(value);
78	}
79	
80	function isVisibility(value: string): value is Visibility {
81	  return (VISIBILITIES as readonly string[]).includes(value);
82	}
83	
84	/**
85	 * Форма создания во втором нативном `<dialog>` без URL. Монтируется только пока форма открыта
86	 * (состояние открытости в `app`); при размонтировании закрывает диалог и возвращает фокус.
87	 */
88	export function CreateSessionDialog({
89	  filtersActive,
90	  onClose,
91	  onCreated,
92	  onOpenSession,
93	  onClearFilters,
94	}: CreateSessionDialogProps) {
95	  const coaches = useCoaches();
96	  const create = useCreateSession(coaches);
97	  const [values, setValues] = useState<FormValues>(INITIAL_VALUES);
98	  const [touched, setTouched] = useState<Partial<Record<FieldName, true>>>({});
99	  const [submitted, setSubmitted] = useState(false);
100	  const [attention, setAttention] = useState(0);
101	  const [confirming, setConfirming] = useState(false);
102	  const [seenCoaches, setSeenCoaches] = useState(coaches.coaches);
103	
104	  const dialogRef = useRef<HTMLDialogElement>(null);
105	  const headingRef = useRef<HTMLHeadingElement>(null);
106	  const submitRef = useRef<HTMLButtonElement>(null);
107	  const keepRef = useRef<HTMLButtonElement>(null);
108	  const cancelRef = useRef<HTMLButtonElement>(null);
109	  const blockRef = useRef<HTMLDivElement>(null);
110	  const selectRef = useRef<HTMLSelectElement>(null);
111	  const closing = useRef(false);
112	  const skipRestore = useRef(false);
113	  const outcomeUnknown = useRef(false);
114	  const coachRetrying = useRef(false);
115	  const restoreAfterConfirm = useRef<HTMLElement | null>(null);
116	  const beforeConfirm = useRef<HTMLElement | null>(null);
117	
118	  const pending = create.status === "pending";
119	  const createdSession = create.status === "success" ? create.session : null;
120	  const succeeded = createdSession !== null;
121	  const coachIds = coaches.status === "success" ? coaches.coaches.map((coach) => coach.id) : [];
122	
123	  // Выбранный тренер исчез из обновлённого списка: выбор сбрасывается с ошибкой (ui-design 6.4).
124	  if (coaches.status === "success" && seenCoaches !== coaches.coaches) {
125	    setSeenCoaches(coaches.coaches);
126	    if (values.coachId !== "" && !coachIds.includes(values.coachId)) {
127	      setValues({ ...values, coachId: "" });
128	      setTouched({ ...touched, coachId: true });
129	    }
130	  }
131	
132	  const clientErrors = validate(values, { now: currentTime(), coachIds });
133	  const server = splitServerErrors(create.fieldErrors);
134	  const unmatchedErrors = server.unmatched;
135	
136	  function shown(key: ErrorKey): string | undefined {
137	    const serverMessage = server.fields[key];
138	    if (serverMessage !== undefined) return serverMessage;
139	    const clientMessage = clientErrors[key];
140	    if (clientMessage === undefined) return undefined;
141	    if (submitted) return clientMessage;
142	    if (key === "startsAt") return touched.date && touched.time ? clientMessage : undefined;
143	    return touched[key] ? clientMessage : undefined;
144	  }
145	
146	  const errors: Partial<Record<ErrorKey, string>> = {};
147	  for (const key of ERROR_ORDER) errors[key] = shown(key);
148	
149	  // Открытие: showModal, фокус; закрытие при размонтировании и возврат фокуса на открыватель.
150	  useEffect(() => {
151	    const dialog = dialogRef.current;
152	    if (dialog === null) return;
153	    closing.current = false;
154	    const active = document.activeElement;
155	    const opener = active instanceof HTMLElement ? active : null;
156	    if (!dialog.open) dialog.showModal();
157	    return () => {
158	      closing.current = true;
159	      if (dialog.open) dialog.close();
160	      if (!skipRestore.current) restoreFocus(opener);
161	    };
162	  }, []);
163	
164	  // Фокус по виду: форма (в том числе «Create another») или экран успеха.
165	  useEffect(() => {
166	    const dialog = dialogRef.current;
167	    if (dialog === null) return;
168	    if (succeeded) headingRef.current?.focus({ preventScroll: true });
169	    else focusInitial(dialog);
170	  }, [succeeded]);
171	
172	  // Подтверждение закрытия: фокус на «Keep editing»; при отказе возврат туда, где был фокус.
173	  useEffect(() => {
174	    if (confirming) {
175	      keepRef.current?.focus();
176	      return;
177	    }
178	    const previous = restoreAfterConfirm.current;
179	    if (previous === null) return;
180	    restoreAfterConfirm.current = null;
181	    (previous.isConnected ? previous : cancelRef.current)?.focus();
182	  }, [confirming]);
183	
184	  // Повтор загрузки тренеров: фокус на select после успеха, на кнопку повтора после новой ошибки.
185	  useEffect(() => {
186	    if (!coachRetrying.current || coaches.status === "loading") return;
187	    coachRetrying.current = false;
188	    if (coaches.status === "success" && coaches.coaches.length > 0) selectRef.current?.focus();
189	    else document.getElementById(COACH_RETRY_ID)?.focus();
190	  }, [coaches.status, coaches.coaches]);
191	
192	  function focusField(key: ErrorKey): void {
193	    const coachProblem = key === "coachId" && !(coaches.status === "success" && coaches.coaches.length > 0);
194	    const id = coachProblem ? COACH_RETRY_ID : FIELD_IDS[key];
195	    document.getElementById(id)?.focus();
196	  }
197	
198	  const reportCreateError = useEffectEvent(() => {
199	    const first = ERROR_ORDER.find((key) => server.fields[key] !== undefined);
200	    if (first === undefined) blockRef.current?.focus();
201	    else focusField(first);
202	  });
203	  useEffect(() => {
204	    if (create.error !== null) reportCreateError();
205	  }, [create.error]);
206	
207	  function doClose(): void {
208	    onClose({ refetch: outcomeUnknown.current });
209	  }
210	
211	  function requestClose(): void {
212	    if (pending) return;
213	    if (succeeded || !isDirty(values)) {
214	      doClose();
215	      return;
216	    }
217	    const active = document.activeElement;
218	    beforeConfirm.current = active instanceof HTMLElement ? active : null;
219	    setConfirming(true);
220	  }
221	
222	  function keepEditing(): void {
223	    restoreAfterConfirm.current = beforeConfirm.current ?? cancelRef.current;
224	    setConfirming(false);
225	  }
226	
227	  function handleCancelEvent(event: SyntheticEvent<HTMLDialogElement>): void {
228	    // Esc: нативное закрытие отменяется, решает процедура закрытия.
229	    event.preventDefault();
230	    if (confirming) return;
231	    requestClose();
232	  }
233	
234	  function handleNativeClose(): void {
235	    // Браузер мог закрыть диалог повторным Esc несмотря на отменённый `cancel`: возвращаем модальность.
236	    const dialog = dialogRef.current;
237	    // Закрытие нами (cleanup) и StrictMode-перемонтирование (диалог уже снова открыт) не обрабатываются.
238	    if (closing.current || dialog === null || dialog.open) return;
239	    dialog.showModal();
240	    if (!confirming) requestClose();
241	  }
242	
243	  function change(name: FieldName, value: string): void {
244	    setValues((current) => ({ ...current, [name]: value }));
245	    create.clearFieldError(FIELD_SERVER_KEY[name]);
246	  }
247	
248	  function inputProps(name: FieldName) {
249	    return {
250	      name,
251	      value: values[name],
252	      readOnly: pending,
253	      onChange: (event: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => change(name, event.target.value),
254	      onBlur: () => setTouched((current) => ({ ...current, [name]: true })),
255	    };
256	  }
257	
258	  async function handleSubmit(event: FormEvent<HTMLFormElement>): Promise<void> {
259	    event.preventDefault();
260	    if (pending || confirming) return;
261	    setSubmitted(true);
262	    const invalid = ERROR_ORDER.filter((key) => clientErrors[key] !== undefined);
263	    if (invalid.length > 0) {
264	      setAttention(invalid.length);
265	      focusField(invalid[0]);
266	      return;
267	    }
268	    setAttention(0);
269	    const request = toRequest(values);
270	    if (request === null) return;
271	    // Фокус остаётся на кнопке отправки: поля блокируются, фокус не теряется.
272	    submitRef.current?.focus();
273	    const outcome = await create.submit(request);
274	    if (outcome.kind === "success") onCreated();
275	    else if (outcome.kind === "error" && outcome.error.kind !== "api") outcomeUnknown.current = true;
276	    else if (outcome.kind === "blocked") focusField("coachId");
277	  }
278	
279	  function createAnother(): void {
280	    setValues(INITIAL_VALUES);
281	    setTouched({});
282	    setSubmitted(false);
283	    setAttention(0);
284	    create.reset();
285	  }
286	
287	  function openSession(): void {
288	    if (create.session === null) return;
289	    skipRestore.current = true;
290	    onOpenSession(create.session.id);
291	  }
292	
293	  const startsAtShown = errors.startsAt !== undefined;
294	  const timeZone = formatTimeZoneName(currentTime());
295	  // Счётчики считают так же, как validate: после trim.
296	  const descriptionLength = values.description.trim().length;
297	  const notesLength = values.trainerNotes.trim().length;
298	  const coachFieldError = errors.coachId;
299	  const coachListUsable = coaches.status === "success" && coaches.coaches.length > 0;
300	
301	  return (
302	    <dialog
303	      ref={dialogRef}
304	      className="dialog form-dialog"
305	      aria-labelledby="create-title"
306	      onCancel={handleCancelEvent}
307	      onClose={handleNativeClose}
308	    >
309	      <div className="dialog-frame">
310	        <header className="dialog-header">
311	          <div className="dialog-header-main">
312	            {succeeded ? null : (
313	              <h2 id="create-title" ref={headingRef} tabIndex={-1}>
314	                {copy.dialogTitle}
315	              </h2>
316	            )}
317	          </div>
318	          <button
319	            type="button"
320	            className="dialog-close"
321	            aria-label={copy.closeAria}
322	            disabled={pending}
323	            onClick={requestClose}
324	          >
325	            <span aria-hidden="true">×</span>
326	          </button>
327	        </header>
328	
329	        {createdSession !== null ? (
330	          <SuccessScreen
331	            session={createdSession}
332	            filtersActive={filtersActive}
333	            headingRef={headingRef}
334	            onOpenSession={openSession}
335	            onCreateAnother={createAnother}
336	            onClearFilters={onClearFilters}
337	            onClose={doClose}
338	          />
339	        ) : (
340	          <form className="create-form" noValidate aria-busy={pending} onSubmit={handleSubmit}>
341	            <div className="dialog-body">
342	              <Field id="cs-title" label={copy.labels.title} hint={copy.hints.title} error={errors.title}>
343	                <input
344	                  id="cs-title"
345	                  type="text"
346	                  autoComplete="off"
347	                  {...inputProps("title")}
348	                  {...ariaFor("cs-title", { hint: true, error: errors.title !== undefined })}
349	                />
350	              </Field>
351	
352	              <Field id="cs-type" label={copy.labels.type} error={errors.type}>
353	                <select
354	                  id="cs-type"
355	                  name="type"
356	                  value={values.type}
357	                  disabled={pending}
358	                  onChange={(event) => {
359	                    if (isSessionType(event.target.value)) change("type", event.target.value);
360	                  }}
361	                  {...ariaFor("cs-type", { error: errors.type !== undefined })}
362	                >
363	                  {SESSION_TYPES.map((value) => (
364	                    <option key={value} value={value}>
365	                      {copy.typeOptions[value]}
366	                    </option>
367	                  ))}
368	                </select>
369	              </Field>
370	
371	              <div className="field-row">
372	                <Field id="cs-date" label={copy.labels.date} error={errors.date}>
373	                  <input
374	                    id="cs-date"
375	                    type="date"
376	                    autoComplete="off"
377	                    {...inputProps("date")}
378	                    {...ariaFor("cs-date", {
379	                      error: errors.date !== undefined,
380	                      invalid: errors.date !== undefined || startsAtShown,
381	                      extra: startsAtShown ? ["cs-starts-at-error"] : [],
382	                    })}
383	                  />
384	                </Field>
385	                <Field id="cs-time" label={copy.labels.time} hint={copy.hints.time(timeZone)} error={errors.time}>
386	                  <input
387	                    id="cs-time"
388	                    type="time"
389	                    autoComplete="off"
390	                    {...inputProps("time")}
391	                    {...ariaFor("cs-time", {
392	                      hint: true,
393	                      error: errors.time !== undefined,
394	                      invalid: errors.time !== undefined || startsAtShown,
395	                      extra: startsAtShown ? ["cs-starts-at-error"] : [],
396	                    })}
397	                  />
398	                </Field>
399	              </div>
400	              {errors.startsAt === undefined ? null : (
401	                <FieldError id="cs-starts-at-error">{errors.startsAt}</FieldError>
402	              )}
403	
404	              <div className="field-row">
405	                <Field id="cs-duration" label={copy.labels.duration} hint={copy.hints.duration} error={errors.duration}>
406	                  <div className="input-suffix">
407	                    <input
408	                      id="cs-duration"
409	                      type="number"
410	                      inputMode="numeric"
411	                      autoComplete="off"
412	                      {...inputProps("duration")}
413	                      {...ariaFor("cs-duration", {
414	                        hint: true,
415	                        error: errors.duration !== undefined,
416	                        extra: ["cs-duration-unit"],
417	                      })}
418	                    />
419	                    <span id="cs-duration-unit">{copy.units.minutes}</span>
420	                  </div>
421	                </Field>
422	                <Field id="cs-capacity" label={copy.labels.capacity} hint={copy.hints.capacity} error={errors.capacity}>
423	                  <div className="input-suffix">
424	                    <input
425	                      id="cs-capacity"
426	                      type="number"
427	                      inputMode="numeric"
428	                      autoComplete="off"
429	                      {...inputProps("capacity")}
430	                      {...ariaFor("cs-capacity", {
431	                        hint: true,
432	                        error: errors.capacity !== undefined,
433	                        extra: ["cs-capacity-unit"],
434	                      })}
435	                    />
436	                    <span id="cs-capacity-unit">{copy.units.places}</span>
437	                  </div>
438	                </Field>
439	              </div>
440	
441	              <Field
442	                id="cs-coach"
443	                label={copy.labels.coach}
444	                labelFor={coachListUsable || coaches.status === "loading" ? "cs-coach" : null}
445	                error={coachFieldError}
446	              >
447	                {coaches.status === "error" || (coaches.status === "success" && coaches.coaches.length === 0) ? (
448	                  <div role="alert" className="coach-problem">
449	                    <p>{coaches.status === "error" ? copy.coaches.error : copy.coaches.empty}</p>
450	                    <button
451	                      id={COACH_RETRY_ID}
452	                      type="button"
453	                      className="button button-secondary"
454	                      disabled={pending}
455	                      onClick={() => {
456	                        coachRetrying.current = true;
457	                        coaches.retry();
458	                      }}
459	                    >
460	                      {copy.coaches.retry}
461	                    </button>
462	                  </div>
463	                ) : (
464	                  <select
465	                    ref={selectRef}
466	                    id="cs-coach"
467	                    name="coachId"
468	                    value={values.coachId}
469	                    disabled={pending || coaches.status === "loading"}
470	                    onChange={(event) => change("coachId", event.target.value)}
471	                    onBlur={() => setTouched((current) => ({ ...current, coachId: true }))}
472	                    {...ariaFor("cs-coach", { error: coachFieldError !== undefined })}
473	                  >
474	                    <option value="">
475	                      {coaches.status === "loading" ? copy.coaches.loading : copy.coaches.placeholder}
476	                    </option>
477	                    {coaches.coaches.map((coach) => (
478	                      <option key={coach.id} value={coach.id}>
479	                        {coach.name}
480	                      </option>
481	                    ))}
482	                  </select>
483	                )}
484	              </Field>
485	
486	              <Field
487	                id="cs-location-name"
488	                label={copy.labels.locationName}
489	                hint={copy.hints.locationName}
490	                error={errors.locationName}
491	              >
492	                <input
493	                  id="cs-location-name"
494	                  type="text"
495	                  autoComplete="off"
496	                  {...inputProps("locationName")}
497	                  {...ariaFor("cs-location-name", { hint: true, error: errors.locationName !== undefined })}
498	                />
499	              </Field>
500	
501	              <Field
502	                id="cs-location-address"
503	                label={copy.labels.locationAddress}
504	                hint={copy.hints.locationAddress}
505	                error={errors.locationAddress}
506	              >
507	                <input
508	                  id="cs-location-address"
509	                  type="text"
510	                  autoComplete="off"
511	                  {...inputProps("locationAddress")}
512	                  {...ariaFor("cs-location-address", { hint: true, error: errors.locationAddress !== undefined })}
513	                />
514	              </Field>
515	
516	              <fieldset
517	                className="field field-group"
518	                {...ariaFor("cs-visibility", { error: errors.visibility !== undefined, invalid: false })}
519	              >
520	                <legend className="field-label">{copy.labels.visibility}</legend>
521	                <div className="radio-row">
522	                  {VISIBILITIES.map((value) => (
523	                    <label key={value} className="radio-option">
524	                      <input
525	                        id={`cs-visibility-${value === "invite-only" ? "invite" : value}`}
526	                        type="radio"
527	                        name="visibility"
528	                        value={value}
529	                        checked={values.visibility === value}
530	                        disabled={pending}
531	                        onChange={(event) => {
532	                          if (isVisibility(event.target.value)) change("visibility", event.target.value);
533	                        }}
534	                      />
535	                      {copy.visibilityOptions[value]}
536	                    </label>
537	                  ))}
538	                </div>
539	                {errors.visibility === undefined ? null : (
540	                  <FieldError id="cs-visibility-error">{errors.visibility}</FieldError>
541	                )}
542	              </fieldset>
543	
544	              <Field
545	                id="cs-description"
546	                label={copy.labels.description}
547	                optional={copy.labels.optional}
548	                counter={
549	                  descriptionLength >= DESCRIPTION_COUNTER_FROM
550	                    ? copy.counter(descriptionLength, LIMITS.description.max)
551	                    : undefined
552	                }
553	                error={errors.description}
554	              >
555	                <textarea
556	                  id="cs-description"
557	                  rows={3}
558	                  autoComplete="off"
559	                  {...inputProps("description")}
560	                  {...ariaFor("cs-description", {
561	                    counter: descriptionLength >= DESCRIPTION_COUNTER_FROM,
562	                    error: errors.description !== undefined,
563	                  })}
564	                />
565	              </Field>
566	
567	              <Field
568	                id="cs-notes"
569	                label={copy.labels.trainerNotes}
570	                optional={copy.labels.optional}
571	                counter={
572	                  notesLength >= NOTES_COUNTER_FROM
573	                    ? copy.counter(notesLength, LIMITS.trainerNotes.max)
574	                    : undefined
575	                }
576	                error={errors.trainerNotes}
577	              >
578	                <textarea
579	                  id="cs-notes"
580	                  rows={3}
581	                  autoComplete="off"
582	                  {...inputProps("trainerNotes")}
583	                  {...ariaFor("cs-notes", {
584	                    counter: notesLength >= NOTES_COUNTER_FROM,
585	                    error: errors.trainerNotes !== undefined,
586	                  })}
587	                />
588	              </Field>
589	
590	              <div role="status" className="visually-hidden">
591	                {attention > 0 ? copy.attention(attention) : ""}
592	              </div>
593	            </div>
594	
595	            <footer className="dialog-footer form-footer">
596	              {create.error === null ? null : (
597	                <div ref={blockRef} role="alert" tabIndex={-1} className="form-error">
598	                  <p>{copy.formError(create.error)}</p>
